import json

class TestHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        # Print requests to stdout for debugging if needed
        pass

    def do_GET(self):
        self.handle_req('GET')

    def do_HEAD(self):
        self.handle_req('HEAD')

    def do_POST(self):
        self.handle_req('POST')

    def handle_req(self, method):
