            self.send_header('Content-Length', str(len(b'Secret')))
            self.end_headers()
            if method != 'HEAD':
                self.wfile.write(b'Secret')
        elif path == '/dir':
            # Directory redirect or directory response?
            self.send_response(301)
            self.send_header('Location', '/dir/')
            self.end_headers()
        elif path == '/dir/':
            self.send_response(200)
            self.end_headers()
            if method != 'HEAD':
                self.wfile.write(b'Directory Listing')
