use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_long, c_void};
use std::sync::atomic::{AtomicBool, Ordering};

pub static GLOBAL_CURL_INIT: AtomicBool = AtomicBool::new(false);

#[repr(C)]
struct Curl(c_void);

type CurlOption = c_int;

const CURLOPT_URL: CurlOption = 10002;
const CURLOPT_WRITEFUNCTION: CurlOption = 20011;
const CURLOPT_WRITEDATA: CurlOption = 10001;
const CURLOPT_HEADERFUNCTION: CurlOption = 20079;
const CURLOPT_HEADERDATA: CurlOption = 10029;
const CURLOPT_TIMEOUT: CurlOption = 13;
const CURLOPT_SSL_VERIFYPEER: CurlOption = 64;
const CURLOPT_SSL_VERIFYHOST: CurlOption = 81;
const CURLOPT_NOBODY: CurlOption = 44;
const CURLOPT_CUSTOMREQUEST: CurlOption = 10036;
const CURLOPT_HTTPHEADER: CurlOption = 10023;
const CURLOPT_COOKIE: CurlOption = 10022;
const CURLOPT_PROXY: CurlOption = 10004;
const CURLOPT_NOPROXY: CurlOption = 10101;
const CURLOPT_USERPWD: CurlOption = 10005;
const CURLOPT_USERAGENT: CurlOption = 10018;
const CURLOPT_POST: CurlOption = 47;
const CURLOPT_POSTFIELDS: CurlOption = 10015;
const CURLOPT_POSTFIELDSIZE: CurlOption = 60;
const CURLINFO_RESPONSE_CODE: c_int = 0x200002;

#[link(name = "curl")]
extern "C" {
    fn curl_global_init(flags: c_long) -> c_int;
    fn curl_easy_init() -> *mut Curl;
    fn curl_easy_setopt(handle: *mut Curl, option: CurlOption, ...) -> c_int;
    fn curl_easy_perform(handle: *mut Curl) -> c_int;
    fn curl_easy_getinfo(handle: *mut Curl, info: c_int, ...) -> c_int;
    fn curl_easy_cleanup(handle: *mut Curl);
    fn curl_easy_strerror(code: c_int) -> *const c_char;
    fn curl_slist_append(list: *mut c_void, string: *const c_char) -> *mut c_void;
    fn curl_slist_free_all(list: *mut c_void);
}

pub fn init_curl_global() {
    if !GLOBAL_CURL_INIT.swap(true, Ordering::SeqCst) {
        unsafe {
            curl_global_init(0);
        }
    }
}

pub struct HttpResponse {
    pub status_code: u16,
    pub content_len: usize,
    pub body: Vec<u8>,
    pub redirect_url: String,
    pub error_msg: Option<String>,
}

pub struct HttpClientConfig {
    pub verb: String,
    pub timeout: u64,
    pub ignore_cert: bool,
    pub user_agent: Option<String>,
    pub cookies: Vec<String>,
    pub headers: Vec<String>,
    pub username: Option<String>,
    pub password: Option<String>,
    pub proxy: Option<String>,
    pub no_proxy: bool,
}

extern "C" fn write_callback(
    ptr: *mut c_char,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size * nmemb;
    if !userdata.is_null() {
        let body = unsafe { &mut *(userdata as *mut Vec<u8>) };
        let slice = unsafe { std::slice::from_raw_parts(ptr as *const u8, total) };
        body.extend_from_slice(slice);
    }
    total
}

extern "C" fn header_callback(
    ptr: *mut c_char,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size * nmemb;
    if !userdata.is_null() {
        let headers_vec = unsafe { &mut *(userdata as *mut Vec<String>) };
        let slice = unsafe { std::slice::from_raw_parts(ptr as *const u8, total) };
        if let Ok(s) = std::str::from_utf8(slice) {
            headers_vec.push(s.to_string());
        }
    }
    total
}

pub fn fetch_url(url_str: &str, config: &HttpClientConfig) -> HttpResponse {
    init_curl_global();
    unsafe {
        let handle = curl_easy_init();
        if handle.is_null() {
            return HttpResponse {
                status_code: 0,
                content_len: 0,
                body: Vec::new(),
                redirect_url: String::new(),
                error_msg: Some("Failed to initialize curl handle".to_string()),
            };
        }

        let c_url = CString::new(url_str).unwrap();
        curl_easy_setopt(handle, CURLOPT_URL, c_url.as_ptr());
        curl_easy_setopt(handle, CURLOPT_TIMEOUT, config.timeout as c_long);

        if config.ignore_cert {
            curl_easy_setopt(handle, CURLOPT_SSL_VERIFYPEER, 0L);
            curl_easy_setopt(handle, CURLOPT_SSL_VERIFYHOST, 0L);
        }

        if let Some(ref ua) = config.user_agent {
            let c_ua = CString::new(ua.as_str()).unwrap();
            curl_easy_setopt(handle, CURLOPT_USERAGENT, c_ua.as_ptr());
        }

        if !config.cookies.is_empty() {
            let cookie_str = config.cookies.join("; ");
            let c_cookie = CString::new(cookie_str).unwrap();
            curl_easy_setopt(handle, CURLOPT_COOKIE, c_cookie.as_ptr());
        }

        let mut slist: *mut c_void = std::ptr::null_mut();
        for h in &config.headers {
            let c_h = CString::new(h.as_str()).unwrap();
            slist = curl_slist_append(slist, c_h.as_ptr());
        }
        if !slist.is_null() {
            curl_easy_setopt(handle, CURLOPT_HTTPHEADER, slist);
        }

        if let (Some(ref user), Some(ref pass)) = (&config.username, &config.password) {
            let userpass = format!("{}:{}", user, pass);
            let c_up = CString::new(userpass).unwrap();
            curl_easy_setopt(handle, CURLOPT_USERPWD, c_up.as_ptr());
        }

        if config.no_proxy {
            let c_empty = CString::new("").unwrap();
            curl_easy_setopt(handle, CURLOPT_NOPROXY, c_empty.as_ptr());
        } else if let Some(ref p) = config.proxy {
            let c_proxy = CString::new(p.as_str()).unwrap();
            curl_easy_setopt(handle, CURLOPT_PROXY, c_proxy.as_ptr());
        }

        let verb_upper = config.verb.to_uppercase();
        if verb_upper == "HEAD" {
            curl_easy_setopt(handle, CURLOPT_NOBODY, 1L);
        } else if verb_upper == "POST" {
            curl_easy_setopt(handle, CURLOPT_POST, 1L);
            let c_empty = CString::new("").unwrap();
            curl_easy_setopt(handle, CURLOPT_POSTFIELDS, c_empty.as_ptr());
            curl_easy_setopt(handle, CURLOPT_POSTFIELDSIZE, 0L);
        } else if verb_upper != "GET" {
            let c_verb = CString::new(verb_upper.as_str()).unwrap();
            curl_easy_setopt(handle, CURLOPT_CUSTOMREQUEST, c_verb.as_ptr());
        }

        let mut body_bytes: Vec<u8> = Vec::new();
        curl_easy_setopt(
            handle,
            CURLOPT_WRITEFUNCTION,
            write_callback as extern "C" fn(*mut c_char, usize, usize, *mut c_void) -> usize,
        );
        curl_easy_setopt(handle, CURLOPT_WRITEDATA, &mut body_bytes as *mut _ as *mut c_void);

        let mut header_lines: Vec<String> = Vec::new();
        curl_easy_setopt(
            handle,
            CURLOPT_HEADERFUNCTION,
            header_callback as extern "C" fn(*mut c_char, usize, usize, *mut c_void) -> usize,
        );
        curl_easy_setopt(handle, CURLOPT_HEADERDATA, &mut header_lines as *mut _ as *mut c_void);

        let res_code = curl_easy_perform(handle);

        let mut http_code: c_long = 0;
        curl_easy_getinfo(handle, CURLINFO_RESPONSE_CODE, &mut http_code);

        if !slist.is_null() {
            curl_slist_free_all(slist);
        }
        curl_easy_cleanup(handle);

        if res_code != 0 {
            let err_ptr = curl_easy_strerror(res_code);
            let err_msg = if !err_ptr.is_null() {
                CStr::from_ptr(err_ptr).to_string_lossy().to_string()
            } else {
                format!("Curl error code {}", res_code)
            };
            return HttpResponse {
                status_code: 0,
                content_len: 0,
                body: Vec::new(),
                redirect_url: String::new(),
                error_msg: Some(format!(
                    "Curl error after requesting {} : [{}] {}",
                    url_str, res_code, err_msg
                )),
            };
