use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

pub fn load_lines(file_path: &str) -> Vec<String> {
    let path = Path::new(file_path);
    let file = File::open(path).unwrap();
    if file.metadata().unwrap().len() == 0 {
        panic!(
            "Error detecting file encoding of {} - is the file empty?",
            file_path
        );
    }
    let reader = BufReader::new(file);
    let mut lines = Vec::new();
    for line_res in reader.lines() {
        if let Ok(line) = line_res {
            let trimmed = line.trim_end_matches(&['\r', '\n'][..]);
            if !trimmed.is_empty() {
                lines.push(trimmed.to_string());
            }
        }
    }
    lines
}

pub fn get_default_wordlist_path() -> Option<String> {
    if let Ok(exe_path) = std::env::current_exe() {
        if let Some(parent) = exe_path.parent() {
            let default_path = parent.join("dirble_wordlist.txt");
            if default_path.exists() {
                return Some(default_path.to_string_lossy().to_string());
            }
        }
    }
    let current_dir = std::env::current_dir().ok()?;
    let default_path = current_dir.join("dirble_wordlist.txt");
    if default_path.exists() {
        Some(default_path.to_string_lossy().to_string())
    } else {
        None
    }
}
EOF
"}

