use serde::Serialize;
use std::fs::File;
use std::io::Write;

#[derive(Clone, Debug, Serialize)]
pub struct Finding {
    pub url: String,
    pub code: u16,
    pub size: usize,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

impl Finding {
    pub fn type_tag(&self) -> &'static str {
        if self.is_listable {
            "L"
        } else if self.is_directory {
            "D"
        } else {
            "+"
        }
    }

    pub fn format_console(&self, use_color: bool, indent: bool) -> String {
        let tag = self.type_tag();
        let code_str = if use_color {
            match self.code {
                200..=299 => format!("\x1b[32m{}\x1b[0m", self.code),
                300..=399 => format!("\x1b[33m{}\x1b[0m", self.code),
                400..=599 => format!("\x1b[31m{}\x1b[0m", self.code),
                _ => format!("{}", self.code),
            }
        } else {
            format!("{}", self.code)
        };

        let dest_str = if !self.redirect_url.is_empty() {
            format!("|DEST:{}", self.redirect_url)
        } else {
            String::new()
        };

        let prefix = if indent { "  " } else { "" };
        format!(
            "{}{} {} (CODE:{}|SIZE:{}{})",
            prefix, tag, self.url, code_str, self.size, dest_str
        )
    }

    pub fn format_report_line(&self) -> String {
        let tag = self.type_tag();
        let dest_str = if !self.redirect_url.is_empty() {
            format!("|DEST:{}", self.redirect_url)
        } else {
            String::new()
        };
        format!(
            "{} {} (CODE:{}|SIZE:{}{})",
            tag, self.url, self.code, self.size, dest_str
        )
    }
}

pub fn save_txt_report(target_url: &str, findings: &[Finding], file_path: &str) -> std::io::Result<()> {
    let mut file = File::create(file_path)?;
    writeln!(file, "Dirble Scan Report for {}:", target_url)?;
    for f in findings {
        writeln!(file, "{}", f.format_report_line())?;
    }
    writeln!(file)?;
    Ok(())
}

pub fn save_json_report(findings: &[Finding], file_path: &str) -> std::io::Result<()> {
    let mut file = File::create(file_path)?;
    let json_str = serde_json::to_string(findings).unwrap_or_else(|_| "[]".to_string());
    writeln!(file, "{}", json_str)?;
    Ok(())
}

pub fn save_xml_report(findings: &[Finding], file_path: &str) -> std::io::Result<()> {
    let mut file = File::create(file_path)?;
    writeln!(file, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>")?;
    writeln!(file, "<dirble_scan>")?;
    for f in findings {
        writeln!(
            file,
            "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>",
            f.url,
            f.code,
            f.size,
            f.is_directory,
            f.is_listable,
            f.redirect_url,
            f.found_from_listable
        )?;
    }
    write!(file, "</dirble_scan>")?;
    Ok(())
}
EOF
"}

