cat << 'EOF' > src/scanner.rs
use crate::cli::build_cli;
use crate::http::{fetch_url, HttpClientConfig};
use crate::output::{Finding, save_json_report, save_txt_report, save_xml_report};
use crate::wordlist::{get_default_wordlist_path, load_lines};
use chrono::Local;
use crossbeam_channel::{bounded, Receiver, Sender};
use is_terminal_polyfill::IsTerminal;
use rand::Rng;
use regex::Regex;
use std::collections::HashSet;
use std::io::Write;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

#[derive(Clone, Debug)]
pub struct Range {
    pub start: usize,
    pub end: usize,
}

impl Range {
    pub fn parse(s: &str) -> Option<Self> {
        let parts: Vec<&str> = s.split('-').map(|p| p.trim()).collect();
        if parts.len() == 1 {
            let val = parts[0].parse::<usize>().ok()?;
            Some(Range { start: val, end: val })
        } else if parts.len() == 2 {
            let start = parts[0].parse::<usize>().ok()?;
            let end = parts[1].parse::<usize>().ok()?;
            Some(Range { start, end })
        } else {
            None
        }
    }

    pub fn contains(&self, val: usize) -> bool {
        val >= self.start && val <= self.end
    }
}

pub fn is_length_hidden(len: usize, ranges: &[Range]) -> bool {
    ranges.iter().any(|r| r.contains(len))
}

pub fn generate_rand_str(len: usize) -> String {
    const CHARS: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let mut rng = rand::thread_rng();
    (0..len)
        .map(|_| {
            let idx = rng.gen_range(0..CHARS.len());
            CHARS[idx] as char
        })
        .collect()
}

#[derive(Clone, Debug)]
pub enum NonexistentCondition {
    None,
    Code(u16),
    CodeAndSize(u16, usize),
    Skip403,
    Skip401,
}

pub fn detect_nonexistent(
    folder_url: &str,
    config: &HttpClientConfig,
    scan_403: bool,
    scan_401: bool,
    verbose: u8,
) -> NonexistentCondition {
    let mut codes = Vec::new();
    let mut sizes = Vec::new();

    for &len in &[10, 20, 30] {
        let rand_path = generate_rand_str(len);
        let test_url = format!("{}{}", folder_url, rand_path);
        if verbose >= 2 {
            println!(
                "{} [TRACE] (2) dirble::request: [src/request.rs:114] Requesting {}",
                Local::now().format("%H:%M:%S"),
                test_url
            );
        }
        let resp = fetch_url(&test_url, config);
        if resp.status_code != 0 {
            codes.push(resp.status_code);
            sizes.push(resp.content_len);
        }
    }

    if codes.len() < 3 {
        return NonexistentCondition::Code(404);
    }

    if codes[0] == 404 && codes[1] == 404 && codes[2] == 404 {
        println!(
            "[INFO] Detected nonexistent paths for {} are (CODE:404)",
            folder_url
        );
        return NonexistentCondition::Code(404);
    }

    let all_same_code = codes[0] == codes[1] && codes[1] == codes[2];
    let all_same_size = sizes[0] == sizes[1] && sizes[1] == sizes[2];

    if all_same_code {
        let code = codes[0];
        if code == 403 {
            println!(
                "[INFO] Detected nonexistent paths for {} are (CODE:403|SIZE:0)",
                folder_url
            );
            if !scan_403 {
                println!("[INFO] Skipping {}: \n    Scanning of directories returning 403 is disabled.\n    Use the --scan-403 flag to scan this directory,\n    or provide valid session token or credentials.", folder_url);
                return NonexistentCondition::Skip403;
            }
            return NonexistentCondition::Code(403);
        }
        if code == 401 {
            println!(
                "[INFO] Detected nonexistent paths for {} are (CODE:401|SIZE:0)",
                folder_url
            );
            if !scan_401 {
                println!("[INFO] Skipping {}: \n    Scanning of directories returning 401 is disabled.\n    Use the --scan-401 flag to scan this directory,\n    or provide valid session token or credentials.", folder_url);
                return NonexistentCondition::Skip401;
            }
            return NonexistentCondition::Code(401);
        }

        if all_same_size {
            println!(
                "[INFO] Detected nonexistent paths for {} are (CODE:{}|SIZE:{})",
                folder_url, code, sizes[0]
            );
            return NonexistentCondition::CodeAndSize(code, sizes[0]);
        } else {
            println!(
                "[INFO] Detected nonexistent paths for {} are (CODE:{})",
                folder_url, code
            );
            return NonexistentCondition::Code(code);
        }
    }

    println!(
        "[INFO] Detected nonexistent paths for {} are (CODE:404)",
        folder_url
    );
    NonexistentCondition::Code(404)
}

pub fn is_listable_body(body: &[u8]) -> bool {
    let body_str = String::from_utf8_lossy(body).to_lowercase();
    body_str.contains("directory listing for")
        || body_str.contains("parent directory")
        || body_str.contains("to parent directory")
}

pub fn extract_links(body: &[u8], base_url: &str) -> Vec<String> {
    let body_str = String::from_utf8_lossy(body);
    let re = Regex::new(r#"(?i)href=["']([^"']+)["']"#).unwrap();
    let mut links = Vec::new();
    let base_parsed = match url::Url::parse(base_url) {
        Ok(u) => u,
        Err(_) => return links,
    };

    for cap in re.captures_iter(&body_str) {
        let href = &cap[1];
        if href.starts_with('?') || href.starts_with('#') || href.to_lowercase().starts_with("javascript:") {
            continue;
        }
        if let Ok(joined) = base_parsed.join(href) {
            let joined_str = joined.to_string();
            if joined_str.starts_with(base_url) && joined_str != base_url {
                links.push(joined_str);
            }
        }
    }
    links
}

pub fn run_scanner() {
    let matches = build_cli()
        .version("Dirble 1.4.2 (commit c11e5cd, build 2026-06-11)")
        .get_matches();

    let mut targets = Vec::new();

    if let Some(pos_uri) = matches.get_one::<String>("uri_pos") {
        targets.push(pos_uri.clone());
    }

    if let Some(flag_uris) = matches.get_many::<String>("uri") {
        for u in flag_uris {
            targets.push(u.clone());
        }
    }

    if let Some(uri_file) = matches.get_one::<String>("uri_file") {
        let lines = load_lines(uri_file);
        for l in lines {
            targets.push(l);
        }
    }

    if targets.is_empty() {
        let mut cmd = build_cli();
        cmd.print_help().unwrap();
        println!();
        std::process::exit(2);
    }

    let mut norm_targets = Vec::new();
    for mut t in targets {
        if !t.starts_with("http://") && !t.starts_with("https://") {
            t = format!("http://{}", t);
        }
        if !t.ends_with('/') {
            t.push('/');
        }
        norm_targets.push(t);
    }

    let wordlist_path = match matches.get_one::<String>("wordlist") {
        Some(w) => w.clone(),
        None => match get_default_wordlist_path() {
            Some(p) => p,
            None => {
                println!("[ERROR] Unable to find default wordlist");
                std::process::exit(1);
            }
        },
    };

    let raw_wordlist = load_lines(&wordlist_path);

    let mut prefixes = Vec::new();
    if let Some(p_args) = matches.get_many::<String>("prefixes") {
        for p in p_args {
            prefixes.push(p.clone());
        }
    }
    if let Some(p_file) = matches.get_one::<String>("prefix_file") {
        for l in load_lines(p_file) {
            prefixes.push(l);
