    let mut extensions = Vec::new();
    if let Some(e_args) = matches.get_many::<String>("extensions") {
        for e in e_args {
            extensions.push(e.clone());
        }
    }
    if let Some(e_file) = matches.get_one::<String>("extension_file") {
        for l in load_lines(e_file) {
            extensions.push(l);
        }
    }

    let ext_sub = matches.get_flag("ext_sub");
    let force_extension = matches.get_flag("force_extension");
    let ignore_cert = matches.get_flag("ignore_cert");
    let show_htaccess = matches.get_flag("show_htaccess");
    let timeout = *matches.get_one::<u64>("timeout").unwrap_or(&5);
    let max_errors = *matches.get_one::<usize>("max_errors").unwrap_or(&5);
    let json_file = matches.get_one::<String>("json_file").cloned();
    let no_color = matches.get_flag("no_color");
    let output_file = matches.get_one::<String>("output_file").cloned();
    let xml_file = matches.get_one::<String>("xml_file").cloned();
    let output_all = matches.get_one::<String>("output_all").cloned();

    let mut hide_ranges = Vec::new();
    if let Some(hl_args) = matches.get_many::<String>("hide_lengths") {
        for hl in hl_args {
            if let Some(r) = Range::parse(hl) {
                hide_ranges.push(r);
            }
        }
    }

    let burp = matches.get_flag("burp");
    let no_proxy = matches.get_flag("no_proxy");
    let proxy_flag = matches.get_one::<String>("proxy").cloned();
    let proxy = if burp {
        Some("http://localhost:8080".to_string())
    } else {
        proxy_flag
    };

    let max_threads = *matches.get_one::<usize>("max_threads").unwrap_or(&10);
    let wordlist_split = *matches.get_one::<usize>("wordlist_split").unwrap_or(&3);
    let throttle = matches.get_one::<u64>("throttle").cloned();
    let username = matches.get_one::<String>("username").cloned();
    let password = matches.get_one::<String>("password").cloned();
    let scan_listable = matches.get_flag("scan_listable");
    let max_recursion_depth = matches.get_one::<usize>("max_recursion_depth").cloned();
    let disable_recursion = matches.get_flag("disable_recursion");
    let scrape_listable = matches.get_flag("scrape_listable");
    let user_agent = matches.get_one::<String>("user_agent").cloned();

    let mut cookies = Vec::new();
    if let Some(c_args) = matches.get_many::<String>("cookie") {
        for c in c_args {
            cookies.push(c.clone());
        }
    }

    let mut headers = Vec::new();
    if let Some(h_args) = matches.get_many::<String>("header") {
        for h in h_args {
            headers.push(h.clone());
        }
    }

    let silent = matches.get_flag("silent");
    let verbosity = matches.get_count("verbose");
    let verb = matches.get_one::<String>("verb").unwrap_or(&"get".to_string()).clone();

    let mut code_blacklist = HashSet::new();
    if let Some(bl_args) = matches.get_many::<String>("code_blacklist") {
        for bl in bl_args {
            if let Ok(c) = bl.parse::<u16>() {
                code_blacklist.insert(c);
            }
        }
    }

    let mut code_whitelist = HashSet::new();
    let disable_validator_flag = matches.get_flag("disable_validator");
    if let Some(wl_args) = matches.get_many::<String>("code_whitelist") {
        for wl in wl_args {
            if let Ok(c) = wl.parse::<u16>() {
                code_whitelist.insert(c);
            }
        }
    }

    let disable_validator = disable_validator_flag || !code_whitelist.is_empty();
    let scan_401 = matches.get_flag("scan_401");
    let scan_403 = matches.get_flag("scan_403");

    let is_tty = std::io::stdout().is_terminal();
    let use_color = is_tty && !no_color;

    if is_tty && !silent {
        println!("Dirble 1.4.2 (commit c11e5cd, build 2026-06-11)");
        println!("Developed by Izzy Whistlecroft");
        println!("Targets: {}", norm_targets.join(", "));
        println!("Wordlists: {}", wordlist_path);
        if prefixes.is_empty() {
            println!("No Prefixes");
        } else {
            println!("Prefixes: {}", prefixes.join(", "));
        }
        if extensions.is_empty() {
            println!("No Extensions");
        } else {
            println!("Extensions: {}", extensions.join(", "));
        }
        if hide_ranges.is_empty() {
            println!("No lengths hidden");
        } else {
            let ranges_str: Vec<String> = hide_ranges
                .iter()
                .map(|r| {
                    if r.start == r.end {
                        format!("{}", r.start)
                    } else {
                        format!("{}-{}", r.start, r.end)
                    }
                })
                .collect();
            println!("Hidden lengths: {}", ranges_str.join(", "));
        }
        println!();
    }

    let client_config = HttpClientConfig {
        verb,
        timeout,
        ignore_cert,
        user_agent,
        cookies,
        headers,
        username,
        password,
        proxy,
        no_proxy,
    };

    for target_url in &norm_targets {
        let mut findings = Vec::new();
        let mut scan_queue = Vec::<(String, usize)>::new();
        let mut scanned_set = HashSet::new();

        scan_queue.push((target_url.clone(), 0));

        while let Some((folder_url, depth)) = scan_queue.pop() {
            if scanned_set.contains(&folder_url) {
                continue;
            }
            scanned_set.insert(folder_url.clone());

            let nonexistent_cond = if disable_validator {
                NonexistentCondition::None
            } else {
                detect_nonexistent(&folder_url, &client_config, scan_403, scan_401, verbosity)
            };

            match nonexistent_cond {
                NonexistentCondition::Skip403 | NonexistentCondition::Skip401 => continue,
                _ => {}
            }

            if folder_url == *target_url {
                let split = std::cmp::min(max_threads.saturating_sub(2), 8);
                if split > wordlist_split {
                    println!(
                        "[INFO] Increasing wordlist-split for initial scan of {} to {}",
                        folder_url, split
                    );
                }
            }

            let mut candidates = Vec::new();
            for item in &raw_wordlist {
                let base_item = if ext_sub {
                    item.replace("%EXT%", "")
                } else {
                    item.clone()
                };

                let mut item_prefixes = vec!["".to_string()];
                for p in &prefixes {
                    item_prefixes.push(p.clone());
                }

                for p in &item_prefixes {
                    let pref_item = format!("{}{}", p, base_item);

                    if !force_extension {
                        candidates.push(pref_item.clone());
                    }

                    if ext_sub {
                        for ext in &extensions {
                            let sub_item = item.replace("%EXT%", ext);
                            candidates.push(format!("{}{}", p, sub_item));
                        }
                    } else {
                        for ext in &extensions {
                            candidates.push(format!("{}{}", pref_item, ext));
                        }
                    }
                }
            }

            let (tx, rx): (Sender<String>, Receiver<String>) = bounded(candidates.len());
            for c in candidates {
                let _ = tx.send(c);
            }
            drop(tx);

            let findings_mutex = Arc::new(Mutex::new(Vec::<Finding>::new()));

            let mut handles = Vec::new();
            let num_threads = std::cmp::max(1, wordlist_split);

            for thread_idx in 0..num_threads {
                let rx_clone = rx.clone();
                let config_clone = client_config.clone();
                let folder_url_clone = folder_url.clone();
                let nonexistent_cond_clone = nonexistent_cond.clone();
                let findings_mutex_clone = Arc::clone(&findings_mutex);
                let hide_ranges_clone = hide_ranges.clone();
                let code_blacklist_clone = code_blacklist.clone();
                let code_whitelist_clone = code_whitelist.clone();
                let thread_id = thread_idx + 5;

                let handle = thread::spawn(move || {
                    if verbosity >= 1 {
                        println!(
                            "{} [DEBUG] ({}) dirble::request_thread: Scanning {}",
                            Local::now().format("%H:%M:%S"),
                            thread_id,
                            folder_url_clone
                        );
                    }

                    let mut consecutive_errors = 0;

                    while let Ok(candidate_path) = rx_clone.recv() {
                        if throttle.unwrap_or(0) > 0 {
                            thread::sleep(Duration::from_millis(throttle.unwrap()));
                        }

                        let req_url = format!("{}{}", folder_url_clone, candidate_path);

                        if verbosity >= 2 {
                            println!(
                                "{} [TRACE] ({}) dirble::request: [src/request.rs:114] Requesting {}",
                                Local::now().format("%H:%M:%S"),
                                thread_id,
                                req_url
                            );
                        }

                        let resp = fetch_url(&req_url, &config_clone);

                        if resp.status_code == 0 {
                            if let Some(ref err) = resp.error_msg {
                                println!("{}", err);
                            }
                            consecutive_errors += 1;
                            if max_errors > 0 && consecutive_errors >= max_errors {
                                println!("[WARN] {} errored too often during scanning, skipping thread", req_url);
                                break;
                            }
                            continue;
                        } else {
                            consecutive_errors = 0;
                        }

                        let code = resp.status_code;
                        let size = resp.content_len;

                        let is_not_found = match &nonexistent_cond_clone {
                            NonexistentCondition::None => false,
                            NonexistentCondition::Code(c) => code == *c,
                            NonexistentCondition::CodeAndSize(c, s) => code == *c && size == *s,
                            _ => false,
                        };

                        if is_not_found {
                            if verbosity >= 2 {
                                println!(
                                    "{} [TRACE] ({}) dirble::request_thread: [src/request_thread.rs:179] [{}]: matches Not Found condition",
                                    Local::now().format("%H:%M:%S"),
                                    thread_id,
                                    req_url
                                );
                            }
                            continue;
                        }

                        if code_blacklist_clone.contains(&code) {
                            continue;
                        }

                        if !code_whitelist_clone.is_empty() && !code_whitelist_clone.contains(&code) {
                            continue;
                        }

                        if candidate_path.contains(".ht") && code == 403 && !show_htaccess {
                            continue;
                        }

                        if is_length_hidden(size, &hide_ranges_clone) {
                            continue;
                        }

                        let is_listable = (code == 200 || code == 301 || code == 302)
                            && is_listable_body(&resp.body);

                        let mut is_dir = req_url.ends_with('/')
                            || !resp.redirect_url.is_empty()
                            || is_listable;

                        let finding = Finding {
                            url: req_url.clone(),
                            code,
                            size,
                            is_directory: is_dir,
                            is_listable,
                            redirect_url: resp.redirect_url.clone(),
                            found_from_listable: false,
                        };

                        if !silent {
                            if is_tty {
                                println!("{}", finding.format_console(use_color, false));
                            } else {
                                println!("{}", finding.format_console(false, false));
                            }
                        }

                        findings_mutex_clone.lock().unwrap().push(finding);
                    }

                    if verbosity >= 1 {
                        println!(
                            "{} [DEBUG] ({}) dirble::request_thread: Finished scanning {}",
                            Local::now().format("%H:%M:%S"),
                            thread_id,
                            folder_url_clone
                        );
                    }
                });
                handles.push(handle);
            }

            for h in handles {
                let _ = h.join();
            }

            let mut new_findings = findings_mutex.lock().unwrap().clone();

            if scrape_listable {
                let mut scraped_findings = Vec::new();
                for f in &new_findings {
                    if f.is_listable {
                        let resp = fetch_url(&f.url, &client_config);
                        if resp.status_code != 0 {
                            let links = extract_links(&resp.body, &f.url);
                            for link in links {
                                let link_resp = fetch_url(&link, &client_config);
                                if link_resp.status_code != 0 {
                                    let scraped_finding = Finding {
                                        url: link.clone(),
                                        code: link_resp.status_code,
                                        size: link_resp.content_len,
                                        is_directory: link.ends_with('/') || link_resp.status_code == 301 || link_resp.status_code == 302,
                                        is_listable: is_listable_body(&link_resp.body),
                                        redirect_url: link_resp.redirect_url,
                                        found_from_listable: true,
                                    };
                                    if !silent {
                                        if is_tty {
                                            println!("{}", scraped_finding.format_console(use_color, false));
                                        } else {
                                            println!("{}", scraped_finding.format_console(false, false));
                                        }
                                    }
                                    scraped_findings.push(scraped_finding);
                                }
                            }
                        }
                    }
                }
                new_findings.extend(scraped_findings);
            }

            for f in &new_findings {
                findings.push(f.clone());

                if (f.is_directory || f.is_listable) && !disable_recursion {
                    let mut dir_url = f.url.clone();
                    if !dir_url.ends_with('/') {
                        dir_url.push('/');
                    }
                    if max_recursion_depth.map_or(true, |max_d| depth + 1 <= max_d) {
                        if !scanned_set.contains(&dir_url) {
                            scan_queue.push((dir_url, depth + 1));
                        }
                    }
                }
            }
        }

        if is_tty && !silent {
            println!("\nDirble Scan Report for {}:", target_url);
            for f in &findings {
                println!("{}", f.format_console(use_color, true));
            }
        }

        if let Some(ref path) = output_file {
            let _ = save_txt_report(target_url, &findings, path);
        }
        if let Some(ref path) = json_file {
            let _ = save_json_report(&findings, path);
        }
        if let Some(ref path) = xml_file {
            let _ = save_xml_report(&findings, path);
        }
        if let Some(ref prefix) = output_all {
            let _ = save_txt_report(target_url, &findings, &format!("{}.txt", prefix));
            let _ = save_json_report(&findings, &format!("{}.json", prefix));
            let _ = save_xml_report(&findings, &format!("{}.xml", prefix));
        }
    }
}
