                    );
                }
            }

            let mut candidates = Vec::new();
            for item in &raw_wordlist {
                let base_item = if ext_sub {
                    item.replace("%EXT%", "")
                } else {
                    item.clone()
                };

                let mut item_prefixes = vec!["".to_string()];
                for p in &prefixes {
                    item_prefixes.push(p.clone());
                }

                for p in &item_prefixes {
                    let pref_item = format!("{}{}", p, base_item);

