                let handle = thread::spawn(move || {
                    if verbosity >= 1 {
                        println!(
                            "{} [DEBUG] ({}) dirble::request_thread: Scanning {}",
                            Local::now().format("%H:%M:%S"),
                            thread_id,
                            folder_url_clone
                        );
                    }

                    let mut consecutive_errors = 0;

                    while let Ok(candidate_path) = rx_clone.recv() {
                        if throttle.unwrap_or(0) > 0 {
                            thread::sleep(Duration::from_millis(throttle.unwrap()));
                        }

                        let req_url = format!("{}{}", folder_url_clone, candidate_path);

                        if verbosity >= 2 {
                            println!(
                                "{} [TRACE] ({}) dirble::request: [src/request.rs:114] Requesting {}",
                                Local::now().format("%H:%M:%S"),
                                thread_id,
                                req_url
                            );
                        }

                        let resp = fetch_url(&req_url, &config_clone);

                        if resp.status_code == 0 {
                            if let Some(ref err) = resp.error_msg {
                                println!("{}", err);
                            }
                            consecutive_errors += 1;
                            if max_errors > 0 && consecutive_errors >= max_errors {
                                println!("[WARN] {} errored too often during scanning, skipping thread", req_url);
                                break;
                            }
                            continue;
                        } else {
                            consecutive_errors = 0;
                        }

                        let code = resp.status_code;
                        let size = resp.content_len;

                        let is_not_found = match &nonexistent_cond_clone {
                            NonexistentCondition::None => false,
                            NonexistentCondition::Code(c) => code == *c,
                            NonexistentCondition::CodeAndSize(c, s) => code == *c && size == *s,
                            _ => false,
                        };

                        if is_not_found {
                            if verbosity >= 2 {
                                println!(
                                    "{} [TRACE] ({}) dirble::request_thread: [src/request_thread.rs:179] [{}]: matches Not Found condition",
                                    Local::now().format("%H:%M:%S"),
                                    thread_id,
                                    req_url
                                );
                            }
                            continue;
                        }

                        if code_blacklist_clone.contains(&code) {
                            continue;
                        }

                        if !code_whitelist_clone.is_empty() && !code_whitelist_clone.contains(&code) {
                            continue;
                        }

                        if candidate_path.contains(".ht") && code == 403 && !show_htaccess {
                            continue;
                        }

                        if is_length_hidden(size, &hide_ranges_clone) {
                            continue;
                        }

                        let is_listable = (code == 200 || code == 301 || code == 302)
                            && is_listable_body(&resp.body);

                        let is_dir = req_url.ends_with('/')
                            || !resp.redirect_url.is_empty()
                            || is_listable;

                        let finding = Finding {
                            url: req_url.clone(),
                            code,
                            size,
                            is_directory: is_dir,
                            is_listable,
                            redirect_url: resp.redirect_url.clone(),
                            found_from_listable: false,
                        };

                        if !silent {
                            if is_tty {
                                println!("{}", finding.format_console(use_color, false));
                            } else {
                                println!("{}", finding.format_console(false, false));
                            }
                        }

                        findings_mutex_clone.lock().unwrap().push(finding);
                    }

                    if verbosity >= 1 {
                        println!(
                            "{} [DEBUG] ({}) dirble::request_thread: Finished scanning {}",
                            Local::now().format("%H:%M:%S"),
                            thread_id,
                            folder_url_clone
                        );
                    }
                });
                handles.push(handle);
            }

            for h in handles {
                let _ = h.join();
            }

            let mut new_findings = findings_mutex.lock().unwrap().clone();

            if scrape_listable {
                let mut scraped_findings = Vec::new();
                for f in &new_findings {
                    if f.is_listable {
                        let resp = fetch_url(&f.url, &client_config);
                        if resp.status_code != 0 {
                            let links = extract_links(&resp.body, &f.url);
                            for link in links {
                                let link_resp = fetch_url(&link, &client_config);
                                if link_resp.status_code != 0 {
                                    let scraped_finding = Finding {
                                        url: link.clone(),
                                        code: link_resp.status_code,
                                        size: link_resp.content_len,
                                        is_directory: link.ends_with('/') || link_resp.status_code == 301 || link_resp.status_code == 302,
                                        is_listable: is_listable_body(&link_resp.body),
                                        redirect_url: link_resp.redirect_url,
                                        found_from_listable: true,
                                    };
                                    if !silent {
                                        if is_tty {
                                            println!("{}", scraped_finding.format_console(use_color, false));
                                        } else {
                                            println!("{}", scraped_finding.format_console(false, false));
                                        }
                                    }
                                    scraped_findings.push(scraped_finding);
                                }
                            }
                        }
                    }
                }
                new_findings.extend(scraped_findings);
            }

            for f in &new_findings {
                findings.push(f.clone());

                let should_recurse = if f.is_listable {
                    scan_listable
                } else if f.is_directory {
                    !disable_recursion
                } else {
                    false
                };

                if should_recurse {
                    let mut dir_url = f.url.clone();
                    if !dir_url.ends_with('/') {
                        dir_url.push('/');
                    }
                    if max_recursion_depth.map_or(true, |max_d| depth + 1 <= max_d) {
                        if !scanned_set.contains(&dir_url) {
                            scan_queue.push((dir_url, depth + 1));
                        }
                    }
                }
            }
        }

        if is_tty && !silent {
            println!("\nDirble Scan Report for {}:", target_url);
            for f in &findings {
                println!("{}", f.format_console(use_color, true));
            }
        }

        if let Some(ref path) = output_file {
            let _ = save_txt_report(target_url, &findings, path);
        }
        if let Some(ref path) = json_file {
            let _ = save_json_report(&findings, path);
        }
        if let Some(ref path) = xml_file {
            let _ = save_xml_report(&findings, path);
        }
        if let Some(ref prefix) = output_all {
            let _ = save_txt_report(target_url, &findings, &format!("{}.txt", prefix));
            let _ = save_json_report(&findings, &format!("{}.json", prefix));
            let _ = save_xml_report(&findings, &format!("{}.xml", prefix));
        }
    }
}
